#!/usr/bin/env bash
#
# regen-views.sh — regenerate the stamped generated region of every architecture view.
#
# For each view under DIR/architecture/ it reads the command and the input globs from the
# region's opening marker
#   <!-- generated by: <command> | inputs: <glob>[, <glob>...] | sha256: <hex> -->
# runs the command with `bash -c` from the repository root, and pipes its output to
# `living-docs manage view <view> --splice --inputs <globs>`, which keeps the command and
# rewrites the stamp. It runs in a project's CI or on a developer's machine, never inside the
# living-docs binary.
#
# With --check nothing in the real bundle changes: the splice runs against a scratch copy of
# the repository under $TMPDIR, the command runs there too, and each view is compared byte
# for byte. A marker command is shell code: run this only where the repository's own code
# may already run.
#
# A region with no stamp (`<!-- generated by: <command> -->`) is reported as skipped. A
# marker inside a fenced code block of the prose is not a region.
#
# Usage:  regen-views.sh [--check] [--docs-dir DIR]
# Env:    LIVING_DOCS_BIN  the living-docs binary (default: the newer of the repository's
#         target/release and target/debug builds, else living-docs on PATH)
# Exit:   0 = every region is current (or regenerated), 1 = a region would change under
#         --check, a command failed, or a marker could not be parsed, 2 = usage error.

set -euo pipefail

bin="${LIVING_DOCS_BIN:-living-docs}"
docs_dir="docs"
check=0
fail=0
command_text=""
globs=()

usage() {
	echo "usage: regen-views.sh [--check] [--docs-dir DIR]" >&2
	exit 2
}

parse_args() {
	while [[ $# -gt 0 ]]; do
		case "$1" in
		--check) check=1 ;;
		--docs-dir)
			[[ $# -ge 2 ]] || usage
			docs_dir="$2"
			shift
			;;
		*) usage ;;
		esac
		shift
	done
}

# The nearest ancestor of $1 holding a .git entry, the repository root.
repository_root() {
	local dir parent
	dir="$(cd "$1" && pwd -P)" || return 1
	while [[ ! -e "$dir/.git" && ! -L "$dir/.git" ]]; do
		parent="$(dirname "$dir")"
		[[ "$parent" != "$dir" ]] || return 1
		dir="$parent"
	done
	printf '%s\n' "$dir"
}

# The opening marker lines of file $1 that sit outside a fenced code block.
region_markers() {
	awk '/^```/ { fenced = !fenced; next } !fenced && /^<!-- generated by:/ { print }' "$1"
}

# Sets bin to the binary: LIVING_DOCS_BIN, else the newer of the repository's release and
# debug builds, else living-docs on PATH; fails naming LIVING_DOCS_BIN when none runs.
find_binary() {
	local candidate
	bin="${LIVING_DOCS_BIN:-}"
	if [[ -z "$bin" ]]; then
		for candidate in "$root/target/release/living-docs" "$root/target/debug/living-docs"; do
			[[ -x "$candidate" ]] || continue
			if [[ -z "$bin" || "$candidate" -nt "$bin" ]]; then
				bin="$candidate"
			fi
		done
		bin="${bin:-living-docs}"
	fi
	command -v "$bin" >/dev/null 2>&1 || {
		echo "regen-views: no living-docs binary found; set LIVING_DOCS_BIN to its path" >&2
		return 1
	}
}

# Lists the files git would track or could track under $1 that exist, NUL separated.
existing_files() {
	local from="$1" file
	while IFS= read -r -d '' file; do
		if [[ -e "$from/$file" || -L "$from/$file" ]]; then
			printf '%s\0' "$file"
		fi
	done < <(git -C "$from" ls-files -z --cached --others --exclude-standard)
}

# Copies the repository at $1 into $2 with an empty .git, so a splice there reads the same inputs.
copy_repository() {
	local from="$1" to="$2"
	mkdir -p "$to/.git"
	if git -C "$from" rev-parse --git-dir >/dev/null 2>&1; then
		existing_files "$from" | tar -C "$from" --null -T - -cf - | tar -C "$to" -xf -
	else
		tar -C "$from" --exclude=./.git -cf - . | tar -C "$to" -xf -
	fi
}

# Sets command_text and globs from the opening marker line $1. Returns 0 for a stamped
# marker, 1 for one without a stamp, 2 for one it cannot parse.
parse_marker() {
	local marker="$1" list glob
	local stamped='^<!-- generated by: (.*) \| inputs: (.*) \| sha256: [0-9a-f]+ -->$'
	local bare='^<!-- generated by: ([^|]*) -->$'
	if [[ ! "$marker" =~ $stamped ]]; then
		[[ "$marker" =~ $bare ]] && return 1
		return 2
	fi
	command_text="${BASH_REMATCH[1]}"
	list="${BASH_REMATCH[2]}"
	globs=()
	set -f
	while IFS= read -r glob; do
		glob="$(printf '%s' "$glob" | sed 's/^ *//; s/ *$//')"
		[[ -z "$glob" ]] || globs+=("$glob")
	done <<<"${list//,/$'\n'}"
	set +f
	[[ -n "$command_text" && ${#globs[@]} -gt 0 ]] || return 2
}

# Runs the marker's command from the repository $2 and splices its output into view $1
# of the bundle $3.
splice_view() {
	local view="$1" repo="$2" target="$3" output
	output="$(mktemp "$scratch/output.XXXXXX")"
	if ! (cd "$repo" && bash -o pipefail -c "$command_text") >"$output"; then
		echo "regen-views: the command of $view failed: $command_text" >&2
		return 1
	fi
	if ! "$bin" --docs-dir "$target" manage view "architecture/$(basename "$view" .md)" \
		--splice --inputs "${globs[@]}" <"$output" >/dev/null; then
		echo "regen-views: the splice of $view failed; its file name must be a view slug" >&2
		return 1
	fi
}

# Handles one view, $1 its path relative to the bundle.
process_view() {
	local view="$1" markers marker count status=0 target="$bundle" repo="$root"
	markers="$(region_markers "$bundle/$view")"
	[[ -n "$markers" ]] || return 0
	count="$(printf '%s\n' "$markers" | wc -l)"
	if [[ "$count" -gt 1 ]]; then
		echo "regen-views: $view holds $count generated regions; one is supported" >&2
		return 1
	fi
	marker="$markers"
	parse_marker "$marker" || status=$?
	if [[ "$status" -eq 1 ]]; then
		echo "regen-views: skipped $view: its region has no stamp"
		return 0
	elif [[ "$status" -ne 0 ]]; then
		echo "regen-views: cannot parse the marker of $view" >&2
		return 1
	fi
	if [[ "$check" -eq 1 ]]; then
		repo="$scratch/repo"
		target="$repo/$bundle_relative"
	fi
	splice_view "$view" "$repo" "$target" || return 1
	if [[ "$check" -eq 1 ]] && ! cmp -s "$bundle/$view" "$target/$view"; then
		echo "regen-views: the region of $view would change"
		return 1
	fi
}

main() {
	parse_args "$@"
	[[ -d "$docs_dir" ]] || {
		echo "regen-views: $docs_dir is not a directory; pass --docs-dir" >&2
		exit 2
	}
	root="$(repository_root "$docs_dir")" || {
		echo "regen-views: no repository above $docs_dir" >&2
		exit 2
	}
	find_binary || exit 2
	bundle="$(cd "$docs_dir" && pwd -P)"
	bundle_relative="${bundle#"$root"/}"
	scratch="$(mktemp -d "${TMPDIR:-/tmp}/regen-views.XXXXXX")"
	trap 'rm -rf "$scratch"' EXIT
	[[ "$check" -eq 0 ]] || copy_repository "$root" "$scratch/repo"
	local path
	for path in "$bundle"/architecture/*.md; do
		[[ -e "$path" && "$(basename "$path")" != "index.md" ]] || continue
		process_view "architecture/$(basename "$path")" || fail=1
	done
	exit "$fail"
}

main "$@"
